SELECT [Станции_для_сводной(архив)].gruppa_oborud, [Станции_для_сводной(архив)].numb1120, [Топливные затраты].Year, [Zatr_E]/[eotp] AS ud_topl_E, [Zatr_Q]/[Qotp] AS ud_topl_Q, [ZATRATY_SUM]/[B] AS cena, [Станции_для_сводной(архив)].nameoes, [Станции_для_сводной(архив)].nov_Belyaev, [Станции_для_сводной(архив)].NAME
FROM [Станции_для_сводной(архив)] RIGHT JOIN [Топливные затраты] ON ([Станции_для_сводной(архив)].Year = [Топливные затраты].Year) AND ([Станции_для_сводной(архив)].numb1120 = [Топливные затраты].NUMB1120);
